import{_ as t,o as s,c as n,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 14 章 资讯与信息流：收集、筛选、汇总","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 资讯与信息流：收集、筛选、汇总.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 资讯与信息流：收集、筛选、汇总.md"}'),o={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 资讯与信息流：收集、筛选、汇总.md"};function l(i,a,d,p,r,h){return s(),n("div",null,[...a[0]||(a[0]=[e(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 14 章 资讯与信息流：收集、筛选、汇总（易懂版）](../../easy/第14章 资讯与信息流：收集、筛选、汇总（易懂版）.md)</p></div><h1 id="第-14-章-资讯与信息流-收集、筛选、汇总" tabindex="-1">第 14 章 资讯与信息流：收集、筛选、汇总 <a class="header-anchor" href="#第-14-章-资讯与信息流-收集、筛选、汇总" aria-label="Permalink to &quot;第 14 章 资讯与信息流：收集、筛选、汇总&quot;">​</a></h1><blockquote><p>本章目标：掌握信息任务的三种模式（收集/筛选/汇总）、影响判断的写作方法，以及信息来源的诚实边界。<strong>信息爆炸时代，稀缺的不是信息，是判断——我的价值就是帮你把&quot;看不过来&quot;变成&quot;看得完、用得上&quot;。</strong></p></blockquote><h2 id="_14-1-场景-你盯不过来-但漏掉又不行" tabindex="-1">14.1 场景：你盯不过来，但漏掉又不行 <a class="header-anchor" href="#_14-1-场景-你盯不过来-但漏掉又不行" aria-label="Permalink to &quot;14.1 场景：你盯不过来，但漏掉又不行&quot;">​</a></h2><p>每天有大量信息：行业新闻、竞品动态、政策变化、论文更新。一个人盯不过来，但漏掉关键信息又不行。信息类任务的核心矛盾是<strong>注意力稀缺</strong>。</p><p>我的角色是<strong>信息流过滤器 + 汇总器</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>海量信息 →（收集）→ 相关子集 →（筛选）→ 关键几条 →（汇总）→ 可用判断</span></span></code></pre></div><h2 id="_14-2-信息任务的三种模式" tabindex="-1">14.2 信息任务的三种模式 <a class="header-anchor" href="#_14-2-信息任务的三种模式" aria-label="Permalink to &quot;14.2 信息任务的三种模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>用途</th><th>说明</th><th>产出</th></tr></thead><tbody><tr><td><strong>收集</strong></td><td>持续追踪</td><td>定期抓取指定来源的信息</td><td>原始素材清单</td></tr><tr><td><strong>筛选</strong></td><td>去噪</td><td>按主题/关键词/时效过滤</td><td>精简后的候选</td></tr><tr><td><strong>汇总</strong></td><td>产出结论</td><td>生成摘要、简报、对比</td><td>可决策的简报</td></tr></tbody></table><h3 id="_14-2-1-三种模式怎么组合" tabindex="-1">14.2.1 三种模式怎么组合 <a class="header-anchor" href="#_14-2-1-三种模式怎么组合" aria-label="Permalink to &quot;14.2.1 三种模式怎么组合&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>日常：收集 + 筛选（每周跑一次，产出&quot;本周值得看的 10 条&quot;）</span></span>
<span class="line"><span>专项：筛选 + 汇总（针对某个主题，产出&quot;对比报告&quot;）</span></span>
<span class="line"><span>紧急：收集 + 汇总（某个事件，产出&quot;30 分钟速览&quot;）</span></span></code></pre></div><h2 id="_14-3-案例-一份行业资讯简报" tabindex="-1">14.3 案例：一份行业资讯简报 <a class="header-anchor" href="#_14-3-案例-一份行业资讯简报" aria-label="Permalink to &quot;14.3 案例：一份行业资讯简报&quot;">​</a></h2><h3 id="_14-3-1-指令" tabindex="-1">14.3.1 指令 <a class="header-anchor" href="#_14-3-1-指令" aria-label="Permalink to &quot;14.3.1 指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一份《本周 AI 行业简报》：</span></span>
<span class="line"><span>- 范围：AI 产品发布、融资、政策</span></span>
<span class="line"><span>- 每条含：一句话要点 + 来源 + 影响判断</span></span>
<span class="line"><span>- 输出：简报.md，不超过 2 页</span></span></code></pre></div><h3 id="_14-3-2-我的做法-逐步拆解" tabindex="-1">14.3.2 我的做法（逐步拆解） <a class="header-anchor" href="#_14-3-2-我的做法-逐步拆解" aria-label="Permalink to &quot;14.3.2 我的做法（逐步拆解）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 明确来源与关键词（哪些源、什么词才算&quot;相关&quot;）</span></span>
<span class="line"><span>② 收集 → 按&quot;与我相关度&quot;筛选（相关度低的不浪费你眼球）</span></span>
<span class="line"><span>③ 分类汇总（发布/融资/政策）</span></span>
<span class="line"><span>④ 每条写&quot;影响判断&quot;（这条跟我有什么关系）</span></span>
<span class="line"><span>⑤ 你补充遗漏 → 定稿</span></span></code></pre></div><h3 id="_14-3-3-简报的黄金结构" tabindex="-1">14.3.3 简报的黄金结构 <a class="header-anchor" href="#_14-3-3-简报的黄金结构" aria-label="Permalink to &quot;14.3.3 简报的黄金结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 本周 AI 行业简报（第 33 周）</span></span>
<span class="line"><span>## 一、产品发布（3 条）</span></span>
<span class="line"><span>### 1. {一句话要点}</span></span>
<span class="line"><span>- 来源：链接/出处</span></span>
<span class="line"><span>- 影响判断：{和我/业务的关系 + 该做什么}</span></span>
<span class="line"><span>## 二、融资动态（2 条）</span></span>
<span class="line"><span>## 三、政策变化（2 条）</span></span>
<span class="line"><span>## 四、本周重点提示（1~2 条最值得关注）</span></span></code></pre></div><h2 id="_14-4-影响判断-信息的真正价值" tabindex="-1">14.4 影响判断：信息的真正价值 <a class="header-anchor" href="#_14-4-影响判断-信息的真正价值" aria-label="Permalink to &quot;14.4 影响判断：信息的真正价值&quot;">​</a></h2><h3 id="_14-4-1-从-发生了什么-到-我们该做什么" tabindex="-1">14.4.1 从&quot;发生了什么&quot;到&quot;我们该做什么&quot; <a class="header-anchor" href="#_14-4-1-从-发生了什么-到-我们该做什么" aria-label="Permalink to &quot;14.4.1 从&quot;发生了什么&quot;到&quot;我们该做什么&quot;&quot;">​</a></h3><p>汇总不是复读新闻，而是回答三个递进问题：</p><table tabindex="0"><thead><tr><th>层次</th><th>问题</th><th>例子</th></tr></thead><tbody><tr><td>发生了什么</td><td>这条信息说了什么</td><td>某平台发布无代码 Agent 工具</td></tr><tr><td>跟我有关吗</td><td>对我/我的业务有何影响</td><td>内部低代码方案可替代</td></tr><tr><td>我该做什么</td><td>下一步动作是什么</td><td>两周内安排试用评估</td></tr></tbody></table><h3 id="_14-4-2-影响判断的写法公式" tabindex="-1">14.4.2 影响判断的写法公式 <a class="header-anchor" href="#_14-4-2-影响判断的写法公式" aria-label="Permalink to &quot;14.4.2 影响判断的写法公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;这条信息 → 具体影响（谁的什么受影响）→ 建议动作（下一步做什么）&quot;</span></span></code></pre></div><p><strong>这才是简报的价值</strong>：从&quot;发生了什么&quot;推进到&quot;我们该做什么&quot;。没有影响判断的简报 = 新闻复读机。</p><h2 id="_14-5-筛选的标准-不是越多越好" tabindex="-1">14.5 筛选的标准：不是越多越好 <a class="header-anchor" href="#_14-5-筛选的标准-不是越多越好" aria-label="Permalink to &quot;14.5 筛选的标准：不是越多越好&quot;">​</a></h2><p>筛选的目的是<strong>帮你省注意力</strong>，所以标准要明确：</p><table tabindex="0"><thead><tr><th>筛选维度</th><th>问题</th></tr></thead><tbody><tr><td>相关度</td><td>与你的行业/业务直接相关吗？</td></tr><tr><td>时效性</td><td>现在是新信息吗？还来得及用吗？</td></tr><tr><td>可信度</td><td>来源可靠吗？需要交叉验证吗？</td></tr><tr><td>行动价值</td><td>看完能做什么决定/动作吗？</td></tr></tbody></table><h3 id="_14-5-1-精选-vs-全量" tabindex="-1">14.5.1 精选 vs 全量 <a class="header-anchor" href="#_14-5-1-精选-vs-全量" aria-label="Permalink to &quot;14.5.1 精选 vs 全量&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每日简报：5~10 条精选（只留高价值）</span></span>
<span class="line"><span>周报汇总：10~20 条（可以稍全）</span></span>
<span class="line"><span>专项研究：全量收集 + 结构化对比（那是另一类任务）</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">筛选心态</p><p><strong>&quot;少而精&quot;永远优于&quot;多而全&quot;。</strong> 一份 10 条的精选简报，胜过 50 条的全文罗列。你的时间比信息贵。</p></div><h2 id="_14-6-信息来源的边界-诚实版" tabindex="-1">14.6 信息来源的边界（诚实版） <a class="header-anchor" href="#_14-6-信息来源的边界-诚实版" aria-label="Permalink to &quot;14.6 信息来源的边界（诚实版）&quot;">​</a></h2><ul><li>我能访问的信息取决于<strong>你提供的工具和链接</strong>——我不隐身挂网，也浏览不了所有网站；</li><li>拿不到原文的，我标注&quot;来源待核实&quot;，<strong>不编造引用</strong>；</li><li>重要信息（数据、政策原文）<strong>建议你核对原文后再传播</strong>。</li></ul><h3 id="_14-6-1-如何配合我获取信息" tabindex="-1">14.6.1 如何配合我获取信息 <a class="header-anchor" href="#_14-6-1-如何配合我获取信息" aria-label="Permalink to &quot;14.6.1 如何配合我获取信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>你做什么</th></tr></thead><tbody><tr><td>有固定信息源</td><td>给我链接列表、RSS、或文件（导出/保存）</td></tr><tr><td>有工具可用</td><td>告诉我可用哪些工具（如浏览器工具）</td></tr><tr><td>需要联网核实</td><td>提供链接，或把页面内容贴给我</td></tr></tbody></table><h2 id="_14-7-信息简报的进阶-沉淀与自动化" tabindex="-1">14.7 信息简报的进阶：沉淀与自动化 <a class="header-anchor" href="#_14-7-信息简报的进阶-沉淀与自动化" aria-label="Permalink to &quot;14.7 信息简报的进阶：沉淀与自动化&quot;">​</a></h2><ul><li>把&quot;简报模板&quot;存成记忆/Skill，下次一句话触发；</li><li>把收集流程做成自动化工作流（见第 15 章）；</li><li>把重点信息沉淀进知识库（见第 13 章）。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一句话触发：</span></span>
<span class="line"><span>&quot;生成本周简报&quot; → 自动走：收集 → 筛选 → 汇总 → 草稿 → 你审阅</span></span></code></pre></div><h2 id="_14-8-练习" tabindex="-1">14.8 练习 <a class="header-anchor" href="#_14-8-练习" aria-label="Permalink to &quot;14.8 练习&quot;">​</a></h2><ol><li>告诉我你的行业和关注主题，让我生成一份简报框架；</li><li>给我一批资料链接/文件，让我筛选出最相关的 5 条并写影响判断；</li><li>用 14.4 的公式，把其中一条改写成&quot;影响 + 动作&quot;式判断；</li><li>把&quot;简报模板&quot;存成记忆，下次一键复用。</li></ol><hr><blockquote><p>小结：信息爆炸时代，稀缺的不是信息，是<strong>判断</strong>。我帮你完成从&quot;收集&quot;到&quot;判断&quot;的最后一步——记住：<strong>没有影响判断的简报，只是新闻复读机。</strong> 下一章，让任务自己跑——自动化工作流。</p></blockquote>`,42)])])}const b=t(o,[["render",l]]);export{u as __pageData,b as default};
